CREATE TABLE "django_admin_log" ("id" integer NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "action_time" timestamp with time zone NOT NULL, "user_id" integer NOT NULL, "content_type_id" integer NULL, "object_id" text NULL, "object_repr" varchar(200) NOT NULL, "action_flag" smallint NOT NULL CHECK ("action_flag" >= 0), "change_message" text NOT NULL);
CREATE TABLE "auth_permission" ("id" integer NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "name" varchar(255) NOT NULL, "content_type_id" integer NOT NULL, "codename" varchar(100) NOT NULL);
CREATE TABLE "auth_group" ("id" integer NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "name" varchar(150) NOT NULL UNIQUE);
CREATE TABLE "auth_group_permissions" ("id" integer NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "group_id" integer NOT NULL, "permission_id" integer NOT NULL);
CREATE TABLE "auth_user" ("id" integer NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "password" varchar(128) NOT NULL, "last_login" timestamp with time zone NULL, "is_superuser" boolean NOT NULL, "username" varchar(150) NOT NULL UNIQUE, "first_name" varchar(150) NOT NULL, "last_name" varchar(150) NOT NULL, "email" varchar(254) NOT NULL, "is_staff" boolean NOT NULL, "is_active" boolean NOT NULL, "date_joined" timestamp with time zone NOT NULL);
CREATE TABLE "auth_user_groups" ("id" integer NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "user_id" integer NOT NULL, "group_id" integer NOT NULL);
CREATE TABLE "auth_user_user_permissions" ("id" integer NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "user_id" integer NOT NULL, "permission_id" integer NOT NULL);
CREATE TABLE "django_content_type" ("id" integer NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "app_label" varchar(100) NOT NULL, "model" varchar(100) NOT NULL);
CREATE TABLE "django_session" ("session_key" varchar(40) NOT NULL PRIMARY KEY, "session_data" text NOT NULL, "expire_date" timestamp with time zone NOT NULL);
CREATE TABLE "core_company" ("id" varchar(50) NOT NULL PRIMARY KEY, "name" varchar(200) NOT NULL, "gst_number" varchar(20) NULL, "remarks" text NULL, "created_at" timestamp with time zone NOT NULL);
CREATE TABLE "core_plant" ("id" varchar(50) NOT NULL PRIMARY KEY, "company_id" varchar(50) NULL, "name" varchar(150) NOT NULL, "plant_type" varchar(30) NOT NULL, "is_active" boolean NOT NULL, "remarks" text NULL, "created_at" timestamp with time zone NOT NULL);
CREATE TABLE "core_department" ("id" varchar(50) NOT NULL PRIMARY KEY, "plant_id" varchar(50) NULL, "name" varchar(150) NOT NULL, "is_shared_across_plants" boolean NOT NULL, "remarks" text NULL, "created_at" timestamp with time zone NOT NULL);
CREATE TABLE "core_designation" ("id" varchar(50) NOT NULL PRIMARY KEY, "department_id" varchar(50) NULL, "title" varchar(150) NOT NULL, "hierarchy_level" integer NOT NULL, "remarks" text NULL, "created_at" timestamp with time zone NOT NULL);
CREATE TABLE "core_employee" ("id" varchar(50) NOT NULL PRIMARY KEY, "department_id" varchar(50) NULL, "designation_id" varchar(50) NULL, "plant_id" varchar(50) NULL, "name" varchar(150) NOT NULL, "user_account_id" varchar(50) NULL, "status" varchar(20) NOT NULL, "remarks" text NULL, "created_at" timestamp with time zone NOT NULL);
CREATE TABLE "core_employeedetail" ("id" varchar(50) NOT NULL PRIMARY KEY, "employee_id" varchar(50) NOT NULL UNIQUE, "date_of_birth" date NULL, "gender" varchar(20) NULL, "contact_number" varchar(20) NULL, "address" text NULL, "date_of_joining" date NULL, "emergency_contact_name" varchar(150) NULL, "emergency_contact_number" varchar(20) NULL, "remarks" text NULL);
CREATE TABLE "core_employeebankaccount" ("id" varchar(50) NOT NULL PRIMARY KEY, "employee_id" varchar(50) NOT NULL, "bank_name" varchar(150) NOT NULL, "account_holder_name" varchar(150) NOT NULL, "account_number" varchar(40) NOT NULL, "ifsc_code" varchar(20) NOT NULL, "is_primary" boolean NOT NULL, "remarks" text NULL);
CREATE TABLE "core_role" ("id" varchar(50) NOT NULL PRIMARY KEY, "name" varchar(100) NOT NULL UNIQUE, "remarks" text NULL);
CREATE TABLE "core_employeerole" ("id" varchar(50) NOT NULL PRIMARY KEY, "employee_id" varchar(50) NOT NULL, "role_id" varchar(50) NOT NULL);
CREATE TABLE "core_permission" ("id" varchar(50) NOT NULL PRIMARY KEY, "designation_id" varchar(50) NULL, "role_id" varchar(50) NULL, "module" varchar(80) NOT NULL, "process_type_id" varchar(50) NULL, "master_category_id" varchar(50) NULL, "action" varchar(40) NULL, "can_view" boolean NOT NULL, "can_create" boolean NOT NULL, "can_edit" boolean NOT NULL, "can_delete" boolean NOT NULL, "can_approve" boolean NOT NULL);
CREATE TABLE "core_vendor" ("id" varchar(50) NOT NULL PRIMARY KEY, "name" varchar(200) NOT NULL, "gst_number" varchar(20) NULL, "contact_info" jsonb NULL, "is_active" boolean NOT NULL, "remarks" text NULL, "created_at" timestamp with time zone NOT NULL);
CREATE TABLE "core_machine" ("id" varchar(50) NOT NULL PRIMARY KEY, "plant_id" varchar(50) NULL, "department_id" varchar(50) NULL, "machine_type_id" varchar(50) NULL, "code" varchar(40) NOT NULL UNIQUE, "name" varchar(150) NOT NULL, "capacity" numeric(14, 3) NULL, "registration_number" varchar(30) NULL UNIQUE, "fastag_number" varchar(30) NULL, "fastag_status" varchar(20) NULL, "status" varchar(30) NOT NULL, "remarks" text NULL, "created_at" timestamp with time zone NOT NULL);
CREATE TABLE "core_storagelocationblock" ("id" varchar(50) NOT NULL PRIMARY KEY, "department_id" varchar(50) NOT NULL, "start_code" varchar(4) NOT NULL, "end_code" varchar(4) NOT NULL, "remarks" text NULL);
CREATE TABLE "core_storagelocation" ("id" varchar(50) NOT NULL PRIMARY KEY, "unit_id" varchar(50) NULL, "name" varchar(150) NOT NULL, "plant_id" varchar(50) NULL, "department_id" varchar(50) NULL, "storage_location_block_id" varchar(50) NULL, "code" varchar(30) NOT NULL, "capacity" numeric(14, 3) NULL, "status" varchar(30) NOT NULL, "remarks" text NULL);
CREATE TABLE "core_document" ("id" varchar(50) NOT NULL PRIMARY KEY, "entity_table" varchar(80) NOT NULL, "entity_id" varchar(50) NOT NULL, "file_path" varchar(500) NOT NULL, "version_no" integer NOT NULL, "uploaded_by_id" varchar(50) NOT NULL, "remarks" text NULL, "created_at" timestamp with time zone NOT NULL);
CREATE TABLE "core_chartofaccount" ("id" varchar(50) NOT NULL PRIMARY KEY, "code" varchar(30) NOT NULL UNIQUE, "name" varchar(150) NOT NULL, "account_type" varchar(20) NOT NULL, "remarks" text NULL);
CREATE TABLE "ui_menu" ("id" varchar(50) NOT NULL PRIMARY KEY, "menu_name" varchar(150) NOT NULL, "menu_path" varchar(200) NOT NULL, "module_code" varchar(80) NOT NULL, "menu_icon" varchar(50) NOT NULL, "parent_menu_id" varchar(50) NULL, "display_order" integer NOT NULL, "active" boolean NOT NULL, "created_by" varchar(100) NULL, "created_at" timestamp with time zone NOT NULL);
CREATE TABLE "ui_menu_permission" ("id" varchar(50) NOT NULL PRIMARY KEY, "menu_id" varchar(50) NOT NULL, "role_id" varchar(50) NULL, "permission" varchar(50) NOT NULL, "can_view" boolean NOT NULL);
CREATE TABLE "ui_navbar" ("id" varchar(50) NOT NULL PRIMARY KEY, "page_name" varchar(100) NOT NULL UNIQUE, "title" varchar(150) NOT NULL, "icon" varchar(50) NULL, "show_search" boolean NOT NULL, "show_notification" boolean NOT NULL, "show_profile" boolean NOT NULL, "show_logout" boolean NOT NULL, "active" boolean NOT NULL);
CREATE TABLE "ui_form" ("id" varchar(50) NOT NULL PRIMARY KEY, "form_name" varchar(100) NOT NULL UNIQUE, "module" varchar(80) NOT NULL, "title" varchar(150) NOT NULL, "description" text NULL, "active" boolean NOT NULL);
CREATE TABLE "ui_form_field" ("id" varchar(50) NOT NULL PRIMARY KEY, "form_id" varchar(50) NOT NULL, "field_name" varchar(150) NOT NULL, "field_code" varchar(80) NOT NULL, "field_type" varchar(30) NOT NULL, "required" boolean NOT NULL, "default_value" varchar(255) NULL, "options" text NULL, "reference_table" varchar(80) NULL, "field_order" integer NOT NULL, "active" boolean NOT NULL);
CREATE TABLE "ui_modal" ("id" varchar(50) NOT NULL PRIMARY KEY, "modal_name" varchar(100) NOT NULL UNIQUE, "title" varchar(150) NOT NULL, "width" varchar(30) NOT NULL, "height" varchar(30) NOT NULL, "submit_text" varchar(50) NOT NULL, "cancel_text" varchar(50) NOT NULL, "active" boolean NOT NULL, "form_id" varchar(50) NULL);
CREATE TABLE "ui_widget" ("id" varchar(50) NOT NULL PRIMARY KEY, "widget_name" varchar(150) NOT NULL, "widget_type" varchar(50) NOT NULL, "data_source" varchar(200) NULL, "position" integer NOT NULL, "grid_width" varchar(30) NOT NULL, "active" boolean NOT NULL);
CREATE TABLE "ui_theme" ("id" varchar(50) NOT NULL PRIMARY KEY, "theme_name" varchar(100) NOT NULL UNIQUE, "primary_color" varchar(30) NOT NULL, "secondary_color" varchar(30) NOT NULL, "background_color" varchar(30) NOT NULL, "card_bg_color" varchar(30) NOT NULL, "text_color" varchar(30) NOT NULL, "border_color" varchar(30) NOT NULL, "active" boolean NOT NULL);
CREATE TABLE "masters_mastercategory" ("id" varchar(50) NOT NULL PRIMARY KEY, "code" varchar(60) NOT NULL UNIQUE, "name" varchar(150) NOT NULL, "owning_department_id" varchar(50) NULL, "remarks" text NULL, "created_at" timestamp with time zone NOT NULL);
CREATE TABLE "masters_masteritem" ("id" varchar(50) NOT NULL PRIMARY KEY, "category_id" varchar(50) NOT NULL, "code" varchar(80) NOT NULL, "name" varchar(200) NOT NULL, "plant_id" varchar(50) NULL, "department_id" varchar(50) NULL, "attributes" jsonb NULL, "is_active" boolean NOT NULL, "remarks" text NULL, "created_at" timestamp with time zone NOT NULL);
